#[test]
fn unit_metadata() {
    let info = MolarFlow::<f64>::INFO;
    assert_eq!(info.name, "MolarFlow");
    assert_eq!(info.units.len(), MolarFlowUnit::ALL.len());
    for (&unit, unit_info) in MolarFlowUnit::ALL.iter().zip(info.units) {
        assert_eq!(unit.info(), unit_info);
        assert_eq!(format!("{unit:?}"), unit_info.singular);
        assert_eq!(unit.abbreviation(), unit_info.abbreviation);
        assert_eq!(unit.all_abbreviations(), unit_info.abbreviations);
    }
    assert_eq!(info.base_unit, MolarFlowUnit::MolePerSecond.info());
}

#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        MolarFlow::new(v, MolarFlowUnit::MolePerSecond),
        MolarFlow::from_moles_per_second(v)
    );
    assert_eq!(
        MolarFlow::from_base(v).convert_to(MolarFlowUnit::MolePerSecond),
        MolarFlow::from_base(v).as_moles_per_second()
    );
    assert_eq!(
        MolarFlow::new(v, MolarFlowUnit::KilomolePerSecond),
        MolarFlow::from_kilomoles_per_second(v)
    );
    assert_eq!(
        MolarFlow::from_base(v).convert_to(MolarFlowUnit::KilomolePerSecond),
        MolarFlow::from_base(v).as_kilomoles_per_second()
    );
    assert_eq!(
        MolarFlow::new(v, MolarFlowUnit::MolePerMinute),
        MolarFlow::from_moles_per_minute(v)
    );
    assert_eq!(
        MolarFlow::from_base(v).convert_to(MolarFlowUnit::MolePerMinute),
        MolarFlow::from_base(v).as_moles_per_minute()
    );
    assert_eq!(
        MolarFlow::new(v, MolarFlowUnit::KilomolePerMinute),
        MolarFlow::from_kilomoles_per_minute(v)
    );
    assert_eq!(
        MolarFlow::from_base(v).convert_to(MolarFlowUnit::KilomolePerMinute),
        MolarFlow::from_base(v).as_kilomoles_per_minute()
    );
    assert_eq!(
        MolarFlow::new(v, MolarFlowUnit::MolePerHour),
        MolarFlow::from_moles_per_hour(v)
    );
    assert_eq!(
        MolarFlow::from_base(v).convert_to(MolarFlowUnit::MolePerHour),
        MolarFlow::from_base(v).as_moles_per_hour()
    );
    assert_eq!(
        MolarFlow::new(v, MolarFlowUnit::KilomolePerHour),
        MolarFlow::from_kilomoles_per_hour(v)
    );
    assert_eq!(
        MolarFlow::from_base(v).convert_to(MolarFlowUnit::KilomolePerHour),
        MolarFlow::from_base(v).as_kilomoles_per_hour()
    );
    assert_eq!(
        MolarFlow::new(v, MolarFlowUnit::PoundMolePerSecond),
        MolarFlow::from_pound_moles_per_second(v)
    );
    assert_eq!(
        MolarFlow::from_base(v).convert_to(MolarFlowUnit::PoundMolePerSecond),
        MolarFlow::from_base(v).as_pound_moles_per_second()
    );
    assert_eq!(
        MolarFlow::new(v, MolarFlowUnit::PoundMolePerMinute),
        MolarFlow::from_pound_moles_per_minute(v)
    );
    assert_eq!(
        MolarFlow::from_base(v).convert_to(MolarFlowUnit::PoundMolePerMinute),
        MolarFlow::from_base(v).as_pound_moles_per_minute()
    );
    assert_eq!(
        MolarFlow::new(v, MolarFlowUnit::PoundMolePerHour),
        MolarFlow::from_pound_moles_per_hour(v)
    );
    assert_eq!(
        MolarFlow::from_base(v).convert_to(MolarFlowUnit::PoundMolePerHour),
        MolarFlow::from_base(v).as_pound_moles_per_hour()
    );
}

#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [MolarFlow; 9] = [
        MolarFlow::const_new(1234.5, MolarFlowUnit::MolePerSecond),
        MolarFlow::const_new(1234.5, MolarFlowUnit::KilomolePerSecond),
        MolarFlow::const_new(1234.5, MolarFlowUnit::MolePerMinute),
        MolarFlow::const_new(1234.5, MolarFlowUnit::KilomolePerMinute),
        MolarFlow::const_new(1234.5, MolarFlowUnit::MolePerHour),
        MolarFlow::const_new(1234.5, MolarFlowUnit::KilomolePerHour),
        MolarFlow::const_new(1234.5, MolarFlowUnit::PoundMolePerSecond),
        MolarFlow::const_new(1234.5, MolarFlowUnit::PoundMolePerMinute),
        MolarFlow::const_new(1234.5, MolarFlowUnit::PoundMolePerHour),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(MolarFlowUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            MolarFlow::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in MolarFlowUnit::ALL {
            assert_eq!(
                MolarFlow::const_new(v, unit).as_base().to_bits(),
                MolarFlow::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = MolarFlow::from_base(v);
        let auto = q.auto_unit();
        assert_close(MolarFlow::new(auto.value, auto.unit).as_base(), v, F64_TOL);
        for &unit in MolarFlowUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        MolarFlow::from_base(0.0).auto_unit().unit,
        MolarFlowUnit::MolePerSecond
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "mol/s".parse::<MolarFlowUnit>(),
        Ok(MolarFlowUnit::MolePerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "mol/s").parse::<MolarFlow>(),
        Ok(MolarFlow::new(2.5, MolarFlowUnit::MolePerSecond))
    );
    assert_eq!(
        "kmol/s".parse::<MolarFlowUnit>(),
        Ok(MolarFlowUnit::KilomolePerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "kmol/s").parse::<MolarFlow>(),
        Ok(MolarFlow::new(2.5, MolarFlowUnit::KilomolePerSecond))
    );
    assert_eq!(
        "mol/min".parse::<MolarFlowUnit>(),
        Ok(MolarFlowUnit::MolePerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "mol/min").parse::<MolarFlow>(),
        Ok(MolarFlow::new(2.5, MolarFlowUnit::MolePerMinute))
    );
    assert_eq!(
        "kmol/min".parse::<MolarFlowUnit>(),
        Ok(MolarFlowUnit::KilomolePerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "kmol/min").parse::<MolarFlow>(),
        Ok(MolarFlow::new(2.5, MolarFlowUnit::KilomolePerMinute))
    );
    assert_eq!(
        "mol/h".parse::<MolarFlowUnit>(),
        Ok(MolarFlowUnit::MolePerHour)
    );
    assert_eq!(
        format!("2.5 {}", "mol/h").parse::<MolarFlow>(),
        Ok(MolarFlow::new(2.5, MolarFlowUnit::MolePerHour))
    );
    assert_eq!(
        "kmol/h".parse::<MolarFlowUnit>(),
        Ok(MolarFlowUnit::KilomolePerHour)
    );
    assert_eq!(
        format!("2.5 {}", "kmol/h").parse::<MolarFlow>(),
        Ok(MolarFlow::new(2.5, MolarFlowUnit::KilomolePerHour))
    );
    assert_eq!(
        "lbmol/s".parse::<MolarFlowUnit>(),
        Ok(MolarFlowUnit::PoundMolePerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "lbmol/s").parse::<MolarFlow>(),
        Ok(MolarFlow::new(2.5, MolarFlowUnit::PoundMolePerSecond))
    );
    assert_eq!(
        "lbmol/min".parse::<MolarFlowUnit>(),
        Ok(MolarFlowUnit::PoundMolePerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "lbmol/min").parse::<MolarFlow>(),
        Ok(MolarFlow::new(2.5, MolarFlowUnit::PoundMolePerMinute))
    );
    assert_eq!(
        "lbmol/h".parse::<MolarFlowUnit>(),
        Ok(MolarFlowUnit::PoundMolePerHour)
    );
    assert_eq!(
        format!("2.5 {}", "lbmol/h").parse::<MolarFlow>(),
        Ok(MolarFlow::new(2.5, MolarFlowUnit::PoundMolePerHour))
    );
    assert_eq!(
        "1 not-a-unit".parse::<MolarFlow>(),
        Err(ParseError::UnknownUnit)
    );
}

